  "implementation": "def solve(case):
    edges = case['edges']
    communities = case['communities']
    resolution = case['resolution']

    # build symmetric adjacency and degrees
    adj = {}
    deg = {}
    for u, v, w in edges:
        adj.setdefault(u, {})[v] = adj[u].get(v, 0) + w
        adj.setdefault(v, {})[u] = adj[v].get(u, 0) + w
        deg[u] = deg.get(u, 0) + w
        deg[v] = deg.get(v, 0) + w

    m = sum(w for _, _, w in edges)  # total weight

    nodes = sorted(communities.keys())

    # current partition
    comm_of_node = dict(communities)

    # total degree per community
    comm_deg = {}
    for node, comm in comm_of_node.items():
        comm_deg[comm] = comm_deg.get(comm, 0) + deg[node]

    moves = []

    for node in nodes:
        cur_comm = comm_of_node[node]
        k_i = deg[node]

        # sum of weights from node to each community
        ki_in = {}
        for nb, w in adj.get(node, {}).items():
            nb_comm = comm_of_node[nb]
            ki_in[nb_comm] = ki_in.get(nb_comm, 0) + w

        best_comm = cur_comm
        best_delta = 0.0
        candidates = set(ki_in.keys()) | {cur_comm}

        for cand_comm in candidates:
            if cand_comm == cur_comm:
                delta = 0.0
            else:
                ki_in_B = ki_in.get(cand_comm, 0)
                ki_in_A = ki_in.get(cur_comm, 0)
                # 2m * delta_Q
                delta = (ki_in_B - ki_in_A) - resolution * (k_i * (comm_deg.get(cand_comm, 0) - comm_deg[cur_comm] + k_i) / m)
            if delta > best_delta or (delta == best_delta and cand_comm < best_comm):
                best_delta = delta
                best_comm = cand_comm

        if best_comm != cur_comm:
            moves.append({'node': node, 'from': cur_comm, 'to': best_comm})
            # update community degrees
            comm_deg[cur_comm] -= k_i
            comm_deg[best_comm] = comm_deg.get(best_comm, 0) + k_i
            comm_of_node[node] = best_comm

    return {'communities': comm_of_node, 'moves': moves}
